import re

_TOKEN_RE = re.compile(r"<>|<=|>=|[+\-*/(),:=<>]|\d+|[A-Z]\d+|[A-Z]+")

_LIT = 0
_CELL = 1
_NEG = 2
_BIN = 3
_IF = 4
_AGG = 5
_RANGE = 6

_F_CELL = 0
_F_NEG = 1
_F_BIN_L = 2
_F_BIN_R = 3
_F_IF_L = 4
_F_IF_R = 5
_F_AGG = 6

_MISSING = object()
_UNVISITED = object()
_IN_PROGRESS = object()


def _parse_formula(expr: str) -> tuple:
    tokens = _TOKEN_RE.findall(expr)
    n = len(tokens)
    pos = 0

    def parse_expr() -> tuple:
        nonlocal pos
        node = parse_term()
        while pos < n and tokens[pos] in ("+", "-"):
            op = tokens[pos]
            pos += 1
            node = (_BIN, op, node, parse_term())
        return node

    def parse_term() -> tuple:
        nonlocal pos
        node = parse_unary()
        while pos < n and tokens[pos] in ("*", "/"):
            op = tokens[pos]
            pos += 1
            node = (_BIN, op, node, parse_unary())
        return node

    def parse_unary() -> tuple:
        nonlocal pos
        neg = False
        while pos < n and tokens[pos] == "-":
            pos += 1
            neg = not neg
        node = parse_atom()
        return (_NEG, node) if neg else node

    def parse_atom() -> tuple:
        nonlocal pos
        tok = tokens[pos]
        if tok == "(":
            pos += 1
            node = parse_expr()
            pos += 1
            return node
        if tok == "IF":
            pos += 2
            left = parse_expr()
            op = tokens[pos]
            pos += 1
            right = parse_expr()
            pos += 1
            then_node = parse_expr()
            pos += 1
            else_node = parse_expr()
            pos += 1
            return (_IF, op, left, right, then_node, else_node)
        if tok in ("SUM", "MIN", "MAX"):
            pos += 2
            args = []
            while True:
                if pos + 1 < n and tokens[pos + 1] == ":":
                    t1 = tokens[pos]
                    t2 = tokens[pos + 2]
                    pos += 3
                    c1, r1 = ord(t1[0]) - 65, int(t1[1:]) - 1
                    c2, r2 = ord(t2[0]) - 65, int(t2[1:]) - 1
                    if r1 > r2:
                        r1, r2 = r2, r1
                    if c1 > c2:
                        c1, c2 = c2, c1
                    args.append((_RANGE, r1, c1, r2, c2))
                else:
                    args.append(parse_expr())
                if tokens[pos] == ",":
                    pos += 1
                else:
                    break
            pos += 1
            return (_AGG, tok, args)
        if tok[0].isdigit():
            pos += 1
            return (_LIT, int(tok))
        pos += 1
        return (_CELL, (int(tok[1:]) - 1) * 26 + (ord(tok[0]) - 65))

    return parse_expr()


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    val: list = [_MISSING] * 2574
    ast: list = [None] * 2574
    name_to_idx: dict[str, int] = {}

    for name, content in cells.items():
        idx = (int(name[1:]) - 1) * 26 + (ord(name[0]) - 65)
        name_to_idx[name] = idx
        s = content.strip()
        if s.startswith("="):
            val[idx] = _UNVISITED
            ast[idx] = _parse_formula(s[1:])
        else:
            val[idx] = int(s)

    for start_idx in name_to_idx.values():
        if val[start_idx] is not _UNVISITED:
            continue
        val[start_idx] = _IN_PROGRESS
        stack: list = [(_F_CELL, start_idx)]
        node = ast[start_idx]
        res: int | str | None = None

        while True:
            while node is not None:
                tag = node[0]
                if tag == _LIT:
                    res = node[1]
                    node = None
                elif tag == _CELL:
                    idx = node[1]
                    v = val[idx]
                    if v is _MISSING:
                        res = 0
                        node = None
                    elif v is _UNVISITED:
                        val[idx] = _IN_PROGRESS
                        stack.append((_F_CELL, idx))
                        node = ast[idx]
                    elif v is _IN_PROGRESS:
                        res = "#CYCLE!"
                        node = None
                    else:
                        res = v
                        node = None
                elif tag == _NEG:
                    stack.append((_F_NEG,))
                    node = node[1]
                elif tag == _BIN:
                    stack.append((_F_BIN_L, node[1], node[3]))
                    node = node[2]
                elif tag == _IF:
                    stack.append((_F_IF_L, node[1], node[3], node[4], node[5]))
                    node = node[2]
                else:
                    stack.append([_F_AGG, node[1], node[2], 0, None, 1, 0, 0, 0, 0])
                    res = None
                    node = None

            while stack and node is None:
                frame = stack[-1]
                ftag = frame[0]
                if ftag == _F_CELL:
                    stack.pop()
                    val[frame[1]] = res
                elif ftag == _F_NEG:
                    stack.pop()
                    if type(res) is int:
                        res = -res
                elif ftag == _F_BIN_L:
                    stack.pop()
                    if type(res) is int:
                        stack.append((_F_BIN_R, frame[1], res))
                        node = frame[2]
                elif ftag == _F_BIN_R:
                    stack.pop()
                    if type(res) is int:
                        op = frame[1]
                        lv = frame[2]
                        if op == "+":
                            res = lv + res
                        elif op == "-":
                            res = lv - res
                        elif op == "*":
                            res = lv * res
                        else:
                            if res == 0:
                                res = "#DIV/0!"
                            else:
                                q = abs(lv) // abs(res)
                                res = -q if (lv < 0) != (res < 0) else q
                elif ftag == _F_IF_L:
                    stack.pop()
                    if type(res) is int:
                        stack.append((_F_IF_R, frame[1], res, frame[3], frame[4]))
                        node = frame[2]
                elif ftag == _F_IF_R:
                    stack.pop()
                    if type(res) is int:
                        op = frame[1]
                        lv = frame[2]
                        if op == "=":
                            cond = lv == res
                        elif op == "<>":
                            cond = lv != res
                        elif op == "<":
                            cond = lv < res
                        elif op == "<=":
                            cond = lv <= res
                        elif op == ">":
                            cond = lv > res
                        else:
                            cond = lv >= res
                        node = frame[3] if cond else frame[4]
                else:
                    if res is not None:
                        if type(res) is not int:
                            stack.pop()
                            continue
                        kind = frame[1]
                        acc = frame[4]
                        if acc is None:
                            frame[4] = res
                        elif kind == "SUM":
                            frame[4] = acc + res
                        elif kind == "MIN":
                            if res < acc:
                                frame[4] = res
                        else:
                            if res > acc:
                                frame[4] = res

                    kind = frame[1]
                    args = frame[2]
                    arg_i = frame[3]
                    acc = frame[4]
                    r_cur = frame[5]
                    c_cur = frame[6]
                    r_end = frame[7]
                    c_start = frame[8]
                    c_end = frame[9]

                    while True:
                        if r_cur <= r_end:
                            found_unvisited = False
                            error = None
                            while r_cur <= r_end:
                                idx = r_cur * 26 + c_cur
                                v = val[idx]
                                if c_cur < c_end:
                                    c_cur += 1
                                else:
                                    r_cur += 1
                                    c_cur = c_start

                                if v is _MISSING:
                                    continue
                                if type(v) is int:
                                    if acc is None:
                                        acc = v
                                    elif kind == "SUM":
                                        acc += v
                                    elif kind == "MIN":
                                        if v < acc:
                                            acc = v
                                    else:
                                        if v > acc:
                                            acc = v
                                elif v is _UNVISITED:
                                    frame[3] = arg_i
                                    frame[4] = acc
                                    frame[5] = r_cur
                                    frame[6] = c_cur
                                    frame[7] = r_end
                                    frame[8] = c_start
                                    frame[9] = c_end
                                    val[idx] = _IN_PROGRESS
                                    stack.append((_F_CELL, idx))
                                    node = ast[idx]
                                    found_unvisited = True
                                    break
                                elif v is _IN_PROGRESS:
                                    error = "#CYCLE!"
                                    break
                                else:
                                    error = v
                                    break
                            if found_unvisited:
                                break
                            if error is not None:
                                stack.pop()
                                res = error
                                break

                        if arg_i == len(args):
                            stack.pop()
                            res = 0 if acc is None else acc
                            break
                        arg = args[arg_i]
                        arg_i += 1
                        if arg[0] == _RANGE:
                            r_cur = arg[1]
                            c_start = arg[2]
                            c_cur = c_start
                            r_end = arg[3]
                            c_end = arg[4]
                        else:
                            frame[3] = arg_i
                            frame[4] = acc
                            frame[5] = r_cur
                            frame[6] = c_cur
                            frame[7] = r_end
                            frame[8] = c_start
                            frame[9] = c_end
                            node = arg
                            break

            if not stack and node is None:
                break

    return {name: val[idx] for name, idx in name_to_idx.items()}
